<template><nav class="figma-steps"><button v-for="(item,i) in items" :key="item.key||item.label||item" class="step" :class="{active:i===active,completed:i<active}" type="button" @click="clickable&&emit('change',i)"><span v-if="i>0" class="line left"/><span class="dot"/><span v-if="i<items.length-1" class="line right"/><span class="label">{{ item.label||item }}</span></button></nav></template>
<script setup>defineProps({items:{type:Array,default:()=>[]},active:{type:Number,default:0},clickable:Boolean});const emit=defineEmits(['change'])</script>
<style scoped>.figma-steps{width:303px;height:36px;padding:0;display:flex}.step{position:relative;width:101px;height:36px;padding:0;border:0;background:transparent;font:inherit}.step:disabled{opacity:1}.dot{position:relative;z-index:1;display:block;width:8px;height:8px;margin:0 auto;border-radius:50%;background:#C9CDD4}.active .dot,.completed .dot{background:#00AAA6}.line{position:absolute;top:3px;height:1px;background:#E5E6EB}.line.left{left:0;right:calc(50% + 4px)}.line.right{left:calc(50% + 4px);right:0}.active .line.left,.completed .line.left,.completed .line.right{background:#00AAA6}.label{display:block;margin-top:8px;color:#1D2129;font:400 12px/20px "PingFang SC",sans-serif;white-space:nowrap}</style>
